-- A three-part name identifies an object in Unity Catalog.
SELECT * FROM your_catalog.dg_sam_lab.bronze_loans;
-- catalog       schema       table

SELECT current_user() AS running_as,
       current_catalog() AS active_catalog,
       current_schema() AS active_schema;
SHOW CATALOGS;

USE CATALOG your_catalog;
-- Omit this statement if the schema is already assigned to you.
CREATE SCHEMA IF NOT EXISTS dg_sam_lab;
USE SCHEMA dg_sam_lab;

SELECT current_catalog(), current_schema();

CREATE OR REPLACE TABLE state_ref USING DELTA AS
SELECT * FROM VALUES
 ('VA','Virginia'), ('FL','Florida'), ('NJ','New Jersey')
AS s(state_code,state_name);

DESCRIBE TABLE bronze_loans;
SELECT * FROM bronze_loans ORDER BY event_id;

COMMENT ON TABLE bronze_loans IS
  'Synthetic loan events. Grain: one received event. Lab use only.';
ALTER TABLE bronze_loans ALTER COLUMN loan_id COMMENT
  'Synthetic loan identifier; may repeat across loan events.';

CREATE OR REPLACE VIEW silver_loans_valid AS
SELECT * FROM silver_loan_review WHERE hard_errors = '';

CREATE OR REPLACE VIEW loan_quarantine AS
SELECT * FROM silver_loan_review WHERE hard_errors <> '';

CREATE OR REPLACE TABLE gold_portfolio USING DELTA AS
SELECT state, COUNT(*) AS loan_count, SUM(balance) AS total_balance
FROM silver_loans_valid
GROUP BY state;

SELECT COUNT(*) AS latest_loans FROM silver_loan_review;
SELECT loan_id, hard_errors FROM loan_quarantine ORDER BY loan_id;
SELECT * FROM gold_portfolio ORDER BY state;

CREATE TABLE IF NOT EXISTS file_loans (
  loan_id STRING, balance DECIMAL(18,2), state STRING
) USING DELTA;

COPY INTO file_loans
FROM '/Volumes/your_catalog/dg_sam_lab/lab_files/csv_inbox'
FILEFORMAT = CSV
FORMAT_OPTIONS ('header'='true');

SELECT COUNT(*) AS rows, SUM(balance) AS balance FROM file_loans;

SELECT loan_id, borrower.state AS property_state,
       explode(flags) AS flag
FROM json_loan_events;

CREATE OR REPLACE TABLE mask_demo USING DELTA AS
SELECT loan_id, email FROM silver_loans_valid;

CREATE OR REPLACE FUNCTION mask_email_demo(v STRING)
RETURNS STRING
RETURN CASE WHEN v IS NULL THEN NULL ELSE '[MASKED]' END;

ALTER TABLE mask_demo ALTER COLUMN email
SET MASK mask_email_demo;

SELECT * FROM mask_demo ORDER BY loan_id;

SHOW GRANTS ON TABLE mask_demo;
-- Cleanup on this synthetic copy only:
ALTER TABLE mask_demo ALTER COLUMN email DROP MASK;
SELECT * FROM mask_demo ORDER BY loan_id;

CREATE TABLE IF NOT EXISTS dq_run_results (
  run_id STRING, measured_at TIMESTAMP, rule_version STRING,
  latest_loans BIGINT, quarantined_loans BIGINT,
  loans_with_warnings BIGINT, hard_rule_pass_pct DECIMAL(8,2)
) USING DELTA;

MERGE INTO dq_run_results t
USING (
  SELECT 'lab_baseline_001' AS run_id,
         current_timestamp() AS measured_at,
         'loan_rules_v1' AS rule_version, s.*
  FROM dq_scorecard s
) s ON t.run_id = s.run_id
WHEN NOT MATCHED THEN INSERT *;

SELECT * FROM dq_run_results ORDER BY measured_at DESC;
